`timescale 1ns/1ps

module testbench;

  reg [7:0] a;
  reg [7:0] b;
  wire [7:0] sum;

  // Instantiate the Device Under Test (DUT)
  // This will work with any SimpleAdder or Adder module generated by HFT
  SimpleAdder dut (
    .a(a),
    .b(b),
    .sum(sum)
  );

  initial begin
    // VCD waveform dump setup
    $dumpfile("dump.vcd");
    $dumpvars(0, testbench);

    $display("HFT Simulation Test");
    $display("==================");
    $display("a\tb\tsum");

    // Test case 1: Basic addition
    a = 8'd10; b = 8'd20; #10;
    $display("%d\t%d\t%d", a, b, sum);

    // Test case 2: Larger numbers
    a = 8'd100; b = 8'd27; #10;
    $display("%d\t%d\t%d", a, b, sum);

    // Test case 3: Test overflow behavior
    a = 8'd200; b = 8'd100; #10;
    $display("%d\t%d\t%d (overflow: %d)", a, b, sum, a + b);

    // Test case 4: Test with zeros
    a = 8'd0; b = 8'd0; #10;
    $display("%d\t%d\t%d", a, b, sum);

    // Test case 5: One operand zero
    a = 8'd42; b = 8'd0; #10;
    $display("%d\t%d\t%d", a, b, sum);

    $display("==================");
    $display("Simulation completed successfully!");
    $display("Waveform saved to: dump.vcd");
    $finish;
  end

endmodule